"""Monster Maker headless test (Chrome + SwiftShader WebGL, served over a local web server)."""
import asyncio, os, re, glob, hashlib
from playwright.async_api import async_playwright
import threading, http.server, functools, socketserver
from PIL import Image
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
class _Q(http.server.SimpleHTTPRequestHandler):
    def log_message(self, *a): pass
_srv = socketserver.ThreadingTCPServer(('127.0.0.1', 0), functools.partial(_Q, directory=ROOT)); _srv.daemon_threads = True
threading.Thread(target=_srv.serve_forever, daemon=True).start()
URL = 'http://127.0.0.1:%d/index.html' % _srv.server_address[1]
OUT = ROOT + '/test/shots/'; os.makedirs(OUT, exist_ok=True)
ARGS = ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist', '--autoplay-policy=no-user-gesture-required']
R = []
def check(n, ok, info=''): R.append(bool(ok)); print(('PASS ' if ok else 'FAIL ') + n + (f' — {info}' if info != '' else ''), flush=True)

async def page(b, auto_q=False, manual=True, **kw):
    ctx = await b.new_context(accept_downloads=True, **kw)
    na = '' if auto_q else 'window.__mmNoAutoQ = true;'
    await ctx.add_init_script(f"window.__mmSeed = 4242; window.__mmPDB = true; {na} try{{if(!sessionStorage.getItem('mmInit')){{sessionStorage.setItem('mmInit','1'); localStorage.clear();}}}}catch(e){{}}")
    pg = await ctx.new_page(); pg.set_default_timeout(240000); logs = []
    pg.on('console', lambda m: logs.append(f'{m.type}: {m.text}') if m.type == 'error' else None)
    pg.on('pageerror', lambda e: logs.append(f'PAGEERROR {e}'))
    await pg.goto(URL); await pg.wait_for_function('document.body.classList.contains("ready")', timeout=90000)
    if manual: await pg.evaluate('window.__mmManual = true; __mm.step(1/30, 3)')
    return ctx, pg, logs

def pxs(im): return im.get_flattened_data() if hasattr(im, 'get_flattened_data') else list(im.getdata())
def bright_share(path, thr=250):
    im = Image.open(path).convert('RGB'); px = pxs(im); return sum(1 for r, g, b in px if r >= thr and g >= thr and b >= thr) / (im.width * im.height)
def mean(path): im = Image.open(path).convert('L'); px = pxs(im); return sum(px) / len(px)
async def shot(pg, name):  # let the (slow, software) compositor present the latest frame first
    await pg.evaluate('__mm.step(1/30)'); await pg.wait_for_timeout(1200); await pg.screenshot(path=OUT + name); return OUT + name
LOG = '__mm.log.map(e => e.n)'
async def lg_since(pg, k): return await pg.evaluate(f'__mm.log.slice({k}).map(e => e.n)')
async def mark(pg): return await pg.evaluate('__mm.log.length')
async def until(pg, cond, maxf=4000): return await pg.evaluate(f'(() => {{ let i = 0; for (; i < {maxf} && !({cond}); i++) __mm.stepq(1/30); __mm.step(1/30); return i; }})()')
ROAR_BOT = '''(target) => { for (let i = 0; i < 900 && __mm.S.state === 'show' && __mm.C().kind === 'roar'; i++) { const c = __mm.C(); if (c.phase === 'ready') __mm.roarDown(); else if (c.phase === 'hold' && c.m >= (target < 0 ? (c.zone[0] + c.zone[1]) / 2 : target)) __mm.roarUp(); __mm.stepq(1/30); } __mm.step(1/30); }'''
SCARE_BOT = '''() => { for (let i = 0; i < 3000 && __mm.S.state === 'show' && __mm.C().kind === 'scare'; i++) { for (const v of __mm.vill()) if (v.st === 'walk' && v.rem < 1.2) __mm.scare(v.lane); __mm.stepq(1/30); } __mm.step(1/30); }'''
DANCE_BOT = '''() => { for (let i = 0; i < 3000 && __mm.S.state === 'show' && __mm.C().kind === 'dance'; i++) { const c = __mm.C(); if (c.phase === 'resp' && c.k < c.seq.length && Math.abs(__mm.beat() - (c.respB + c.k)) * __mm.spb() < 0.034) __mm.dance(c.seq[c.k]); __mm.stepq(1/30); } __mm.step(1/30); }'''
async def to_show(pg):  # build -> lever -> cinematic over
    await pg.evaluate('__mm.pull()'); await until(pg, '__mm.S.state === "show"', 400)
async def to_menu(pg):
    if await pg.is_visible('#end.show'): await pg.click('#btnMenu')
    await pg.evaluate('__mm.step(1/30, 3)')
BLACK = '''(n) => { const gl = __mm.renderer.getContext(), px = new Uint8Array(4); let k = 0; for (let i = 0; i < n; i++) { __mm.step(1/30); gl.readPixels(gl.drawingBufferWidth >> 1, gl.drawingBufferHeight >> 1, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px); if (px[0] + px[1] + px[2] < 3) k++; } return k; }'''

