        check('menu: the living monster performs (roar or moves)', await pg.evaluate('__mm.MP.life') == 1 and any(n.startswith('roar') or n == 'growl' or n.startswith('zap') or n == 'spark' for n in lg))
        bs = bright_share(await shot(pg, 'shot-menu.png')); check('menu no glare', bs < .004, round(bs, 5))
        await pg.click('#btnLang'); de = await pg.text_content('#btnPlay'); await shot(pg, 'shot-menu-de.png')
        check('DE toggle', 'Monster-Showdown' in de and 'Freies Labor' in await pg.text_content('#menu'), de)
        await pg.wait_for_timeout(200); await pg.reload(wait_until='load'); await pg.wait_for_function('document.body.classList.contains("ready") && window.__mm'); await pg.evaluate('window.__mmManual = true')
        check('language remembered after reload', 'Monster-Showdown' in await pg.text_content('#btnPlay')); await pg.click('#btnLang')
        check('difficulty default Medium', await pg.evaluate('__mm.diff()') == 'medium' and 'on' in (await pg.get_attribute('#diff [data-d=medium]', 'class') or ''))
        # ---- build ----
        await pg.evaluate('__mm.log.length = 0'); await pg.click('#btnPlay'); await pg.evaluate('__mm.step(1/30, 30)')
        check('Showdown starts in the build dock: 11 part categories, 6 heads', await pg.evaluate('__mm.S.state') == 'build' and await pg.is_visible('#dock.show') and await pg.evaluate("document.querySelectorAll('#tabs button').length") == 11 and await pg.evaluate("document.querySelectorAll('#opts button').length") == 6)
