        check('clicking a part swaps it in with a pop + squelch', await pg.evaluate('__mm.spec().head') == 'pumpkin' and 'splat' in await lg_since(pg, k) and 'on' in (await pg.get_attribute('#opts button[data-p=pumpkin]', 'class') or ''))
        await pg.keyboard.press('ArrowRight'); h1 = await pg.evaluate('__mm.spec().head'); await pg.keyboard.press('ArrowDown'); c1 = await pg.evaluate('__mm.S.cat')
        check('keys: ←→ cycle the part, ↑↓ switch category', h1 == 'dragon' and c1 == 'horns', (h1, c1))
        n_opt = await pg.evaluate('''(() => { let n = 0; for (const c of ['head','horns','eyes','mouth','body','arms','legs','tail','wings','color','pattern']) { const ids = [...document.querySelectorAll('#tabs button')].map(b => b.dataset.c); __mm.S.cat = c; document.querySelector(`#tabs button[data-c=${c}]`).click(); for (const b of document.querySelectorAll('#opts button')) { b.click(); __mm.stepq(1/30); if (__mm.M() && __mm.M().root.parent) n++; } } __mm.step(1/30); return n; })()''')
