        lt = await pg.evaluate('__mm.LV() && __mm.LV().t0'); await pg.evaluate('__mm.pull()'); check('the lever cannot restart a running cinematic', await pg.evaluate('__mm.LV() && __mm.LV().t0') == lt, lt)
